#include <cstdio>
#include <cstdlib>
#include <string>
int main(int argc,char**argv){
 if(argc!=5)return 1;
 const std::size_t n=std::strtoull(argv[1],nullptr,10);
 const int op=std::atoi(argv[2]),reps=std::atoi(argv[3]);
 const std::uint64_t base=std::strtoull(argv[4],nullptr,10);
 std::string s(n,'a');std::uint64_t rng=615334;
