 RollingHash h(s,base);std::uint64_t checksum=0;
 const auto run=[&](){
  if(op==0){RollingHash built(s,base);checksum+=built.whole();}
  if(op==1){h.assign(s);checksum+=h.whole();}
  if(op==2){h.clear();h.assign(s);checksum+=h.whole();}
  if(op==3){std::uint64_t x=0;for(std::size_t i=0;i<n;++i)x+=h.get(i/2,i);checksum+=x;}
 };
 run();checksum=0;const auto begin=std::chrono::steady_clock::now();
 for(int i=0;i<reps;++i)run();
 auto ns=std::chrono::duration_cast<std::chrono::nanoseconds>(std::chrono::steady_clock::now()-begin).count();
 std::printf("%jd %ju\n",static_cast<std::intmax_t>(ns),static_cast<std::uintmax_t>(checksum));
}

